+    	private static boolean isLegacyTlsProtocol(String protocol) {
+    		return protocol != null && (protocol.startsWith("SSL")
+    				|| "TLSv1".equals(protocol)
+    				|| "TLSv1.0".equals(protocol)
+    				|| "TLSv1.1".equals(protocol));
+    	}
