+    				sslSocket.setEnabledProtocols(filterLegacyTlsProtocols(sslSocket.getEnabledProtocols()));
+    				return sslSocket;
+    			} catch (RuntimeException e) {
+    				try {
+    					socket.close();
+    				} catch (IOException ignored) {
+    				}
